#!/bin/bash
set -euo pipefail
ROOT=/www/wwwroot/learn-space
cd "$ROOT"
mkdir -p database export
TMP=$(mktemp)
base64 -d > "$TMP" <<'B64'

B64
unzip -o "$TMP" -d database/
rm -f "$TMP"
chmod +x database/export_g6_up_lesson*.sh
echo '脚本已就绪，开始导出第4、5课…'
python3 database/export_g6_up_lessons.py 4 5
ls -lh export/六年级上册第4课学情.zip export/六年级上册第5课学情.zip
